describe('ToolRegistry static schemas', () => {
  it('reuses the registered weather schema across ten calls @specs/hal-engine-tool-input-validation/spec.md#8', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Weather forecast',
        get inputSchema() {
          schemaReads++;
          return {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
        },
      },
      async input => JSON.stringify(input)
    );

    const responses = [];
    for (let call = 0; call < 10; call++) {
      responses.push(await registry.execute('weather', {location: 'Berlin'}));
    }

    expect({schemaReads, responses}).toEqual({
      schemaReads: 1,
      responses: Array.from({length: 10}, () => ({result: '{\"location\":\"Berlin\"}'})),
    });
  });
});
EOF
